import { Response, NextFunction } from 'express';
import { AuthenticatedRequest, AuthenticatedUser } from '../types';
import { dbAdmin, getSupabaseAdminClient, getSupabaseAnonClient } from '../lib/dbQueryBuilder';
import { query } from '../../src/lib/db';
import { log } from '../utils/logger';
import { resolveStoredFileUrl } from '../utils/storageUrl';
import { createHash } from 'node:crypto';
import { getUserCache, setUserCache, userCacheKeys } from '../services/userCache';

// Extend Express Request globally
declare global {
  namespace Express {
    interface Request {
      user?: AuthenticatedUser;
    }
  }
}

/**
 * Verifies a Supabase session token and returns the authenticated user.
 * Uses Supabase Auth's built-in JWT verification via getUser().
 */
const verifySupabaseSession = async (token: string): Promise<AuthenticatedUser | null> => {
  try {
    const tokenHash = createHash('sha256').update(token).digest('hex');
    const cachedUser = await getUserCache<AuthenticatedUser>(userCacheKeys.auth(tokenHash));
    if (cachedUser) return cachedUser;

    const { data: userData, error } = await getSupabaseAdminClient().auth.getUser(token);
    if (error || !userData?.user) return null;

    const supabaseUser = userData.user;
    const email = supabaseUser.email?.toLowerCase().trim();
    if (!email) return null;

    // Check if user is an admin (via admin_users table)
    const { data: adminRow } = await getSupabaseAdminClient()
      .from('admin_users')
      .select('*')
      .eq('email', email)
      .maybeSingle();

    if (adminRow) {
      const authenticatedUser: AuthenticatedUser = {
        userId: supabaseUser.id,
        email,
        role: 'admin',
        authUserId: supabaseUser.id,
      };
      await setUserCache(userCacheKeys.auth(tokenHash), authenticatedUser, 60);
      return authenticatedUser;
    }

    // Check if user is a student (via users table)
    const { data: studentRow } = await getSupabaseAdminClient()
      .from('users')
      .select('id')
      .eq('email', email)
      .maybeSingle();

    if (studentRow) {
      const authenticatedUser: AuthenticatedUser = {
        userId: studentRow.id,
        email,
        role: 'student',
        authUserId: supabaseUser.id,
      };
      await setUserCache(userCacheKeys.auth(tokenHash), authenticatedUser, 60);
      return authenticatedUser;
    }

    // Authenticated via Supabase but not in our DB — treat as student
    const authenticatedUser: AuthenticatedUser = {
      userId: supabaseUser.id,
      email,
      role: 'student',
      authUserId: supabaseUser.id,
    };
    await setUserCache(userCacheKeys.auth(tokenHash), authenticatedUser, 60);
    return authenticatedUser;
  } catch (err) {
    log.error('[Auth] Error verifying Supabase session:', err);
    return null;
  }
};

/**
 * Middleware: Requires valid Supabase Auth session (via Cookie or Bearer Token).
 * Fetches the user profile from Supabase Auth + admin_users/users tables.
 */
export const requireAuth = async (
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
): Promise<void> => {
  try {
    let token: string | undefined = req.cookies?.sb_session_token;

    if (!token && req.headers.authorization?.startsWith('Bearer ')) {
      token = req.headers.authorization.substring(7);
    }

    if (!token) {
      res.status(401).json({ error: 'Sessão inválida ou expirada. Por favor, faça login novamente.' });
      return;
    }

    const user = await verifySupabaseSession(token);
    if (user) {
      req.user = user;
      return next();
    }

    res.status(401).json({ error: 'Sessão inválida ou expirada. Por favor, faça login novamente.' });
  } catch (err) {
    log.error('[Auth Middleware] Error:', err);
    res.status(500).json({ error: 'Erro interno de autenticação.' });
  }
};

/**
 * Middleware: Requires the authenticated user to have admin role.
 * Must be used AFTER requireAuth.
 */
export const requireAdmin = async (
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
): Promise<void> => {
  await requireAuth(req, res, () => {
    if (req.user?.role !== 'admin') {
      res.status(403).json({ error: 'Acesso negado: recursos exclusivos de administrador.' });
      return;
    }
    next();
  });
};

/**
 * Creates or ensures admin_users record for a Supabase Auth user.
 * Auto-links auth_user_id to admin_users table.
 */
export const ensureAdminUser = async (email: string, authUserId: string): Promise<void> => {
  try {
    const { data: existing } = await getSupabaseAdminClient()
      .from('admin_users')
      .select('id, auth_user_id')
      .eq('email', email)
      .maybeSingle();

    if (existing) {
      if (!existing.auth_user_id || existing.auth_user_id !== authUserId) {
        await query(
          'UPDATE public.admin_users SET auth_user_id = $1, updated_at = NOW() WHERE email = $2',
          [authUserId, email],
        );
      }
    } else {
      const name = email.split('@')[0];
      await getSupabaseAdminClient().from('admin_users').insert([
        {
          email,
          name,
          role: 'admin',
          auth_user_id: authUserId,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        },
      ]);
    }
  } catch (err) {
    log.error('[ensureAdminUser] Error:', err);
  }
};

/**
 * Unified login: authenticates via Supabase Auth,
 * then returns the user profile from admin_users or users table.
 */
export const authenticateUser = async (email: string, password: string) => {
  const supabase = getSupabaseAnonClient();
  let { data: authData, error: authError } = await supabase.auth.signInWithPassword({
    email,
    password,
  });

  if (authError || !authData.user) {
    const cleanEmail = email.toLowerCase().trim();
    const admin = getSupabaseAdminClient();
    const { data: legacyStudent } = await admin
      .from('users')
      .select('password_hash')
      .eq('email', cleanEmail)
      .maybeSingle();

    const passwordHash = legacyStudent?.password_hash;
    if (!passwordHash) return { error: 'E-mail ou senha inválidos.' };

    const bcrypt = await import('bcryptjs');
    const legacyPasswordIsValid = await bcrypt.compare(password, passwordHash).catch(() => false);
    if (!legacyPasswordIsValid) return { error: 'E-mail ou senha inválidos.' };

    const { data: created, error: createError } = await admin.auth.admin.createUser({
      email: cleanEmail,
      password,
      email_confirm: true,
      user_metadata: { role: 'student' },
    });

    if (createError || !created.user) {
      let existingAuthUserId: string | undefined;
      for (let page = 1; page <= 10 && !existingAuthUserId; page++) {
        const { data: pageData, error: listError } = await admin.auth.admin.listUsers({ page, perPage: 100 });
        if (listError) break;
        existingAuthUserId = pageData.users.find(
          (user: { email?: string }) => user.email?.toLowerCase().trim() === cleanEmail,
        )?.id;
        if (pageData.users.length < 100) break;
      }
      if (!existingAuthUserId) return { error: 'E-mail ou senha inválidos.' };
      const { error: updateError } = await admin.auth.admin.updateUserById(existingAuthUserId, {
        password,
        email_confirm: true,
      });
      if (updateError) return { error: 'E-mail ou senha inválidos.' };
    }

    ({ data: authData, error: authError } = await supabase.auth.signInWithPassword({
      email: cleanEmail,
      password,
    }));
    if (authError || !authData.user) return { error: 'E-mail ou senha inválidos.' };
  }

  const cleanEmail = email.toLowerCase().trim();
  const authUserId = authData.user.id;

  // Check admin_users
  const { data: adminRow } = await getSupabaseAdminClient()
    .from('admin_users')
    .select('*')
    .eq('email', cleanEmail)
    .maybeSingle();

  if (adminRow) {
    if (adminRow.auth_user_id !== authUserId) {
      await ensureAdminUser(cleanEmail, authUserId);
    }
    return {
      user: {
        ...adminRow,
        id: adminRow.id,
        role: 'admin',
        answeredQuestions: adminRow.answered_questions || 0,
        correctAnswers: adminRow.correct_answers || 0,
        avatarUrl: resolveStoredFileUrl(adminRow.avatar_url),
      },
      session: authData.session,
    };
  }

  // Check students
  const { data: studentRow } = await getSupabaseAdminClient()
    .from('users')
    .select('*')
    .eq('email', cleanEmail)
    .maybeSingle();

  if (studentRow) {
    return {
      user: {
        ...studentRow,
        id: studentRow.id,
        role: 'student',
        answeredQuestions: studentRow.answered_questions || studentRow.answeredQuestions || 0,
        correctAnswers: studentRow.correct_answers || studentRow.correctAnswers || 0,
        avatarUrl: resolveStoredFileUrl(studentRow.avatar_url || studentRow.avatarUrl || studentRow.avatar),
        showInLeaderboard: studentRow.show_in_leaderboard !== false,
        languagePreference: studentRow.language_preference || 'ingles',
        flashQuizCompleted: !!studentRow.flash_quiz_completed,
      },
      session: authData.session,
    };
  }

  return { error: 'Usuário não encontrado no sistema.' };
};
